var items = payload.data || [];
function targetText(v){ if(v === 'TERMINAL') return '终端'; if(v === 'EDGE') return '边缘云'; if(v === 'CLOUD') return '中心云'; return v || '-'; }
function taskTypeText(v){ if(v === 'LOCAL_QUALITY_CHECK') return '轻量质检'; if(v === 'EDGE_INFERENCE') return '边缘推理'; if(v === 'CLOUD_BATCH_ANALYSIS') return '批量分析'; return v || '-'; }
function statusText(v){ if(v === 'TERMINAL') return '终端本地执行'; if(v === 'EDGE') return '已卸载到边缘云'; if(v === 'CLOUD') return '已卸载到中心云'; return '已决策'; }
items = items.map(function(item){ var target = targetText(item.decisionTarget); return {...item, taskTypeText: taskTypeText(item.taskType), decisionTargetText: target, inputSizeText: (item.inputSizeMb || 0) + ' MB', deadlineText: (item.deadlineMs || '-') + ' ms', terminalLoadText: 'CPU ' + (item.terminalCpuLoad || 0) + '% / 内存 ' + (item.terminalMemoryLoad || 0) + '%', edgeContextText: '负载 ' + (item.edgeLoad || 0) + '% / 时延 ' + (item.edgeLatencyMs || 0) + ' ms', centerContextText: '负载 ' + (item.centerLoad || 0) + '% / 时延 ' + (item.centerLatencyMs || 0) + ' ms', decisionLatencyText: (item.decisionLatencyMs || '-') + ' ms', executeStatusText: statusText(item.decisionTarget)}; });
return {...payload, status: payload.status === 200 ? 0 : payload.status, msg: payload.message, data: {items: items}};
